//! The native core must give exactly the answers the web code gives (tests/golden.tsv, generated by tools/native-golden.mjs).
use wobbly_core::countdown::*;
use wobbly_core::dim::*;
use wobbly_core::sun;
use wobbly_core::morph::{digit, ease_in_out_back, morph};

fn f(s: &str) -> f64 { if s == "nan" { f64::NAN } else { s.parse().unwrap() } }

#[test]
fn matches_the_web_code() {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden.tsv")).unwrap();
    let (mut n_dim, mut n_cd) = (0, 0);
    for (i, line) in text.lines().enumerate().filter(|(_, l)| !l.starts_with('#') && !l.is_empty()) {
        let c: Vec<&str> = line.split('\t').collect();
        let ev = || SunEvents { prev_rise: f(c[2]), prev_set: f(c[3]), next_rise: f(c[4]), next_set: f(c[5]) };
        let at = format!("golden.tsv line {}: {}", i + 1, line);
        match c[0] {
            "nightness" => { let got = nightness(f(c[1]), &ev(), f(c[6]), f(c[7])); assert!((got - f(c[8])).abs() < 1e-9, "{at}: got {got}"); n_dim += 1; }
            "brightness" => { let got = brightness_at(f(c[1]), &ev(), f(c[6]), f(c[8]), f(c[9]), f(c[7])); assert!((got - f(c[10])).abs() < 1e-9, "{at}: got {got}"); n_dim += 1; }
            "groups" => { let g = groups_for(c[1].parse().unwrap(), c[2] == "1"); let want = c[3]; let got = g.iter().map(|x| x.iter().map(|d| d.to_string()).collect::<Vec<_>>().join(",")).collect::<Vec<_>>().join("|"); assert_eq!(got, want, "{at}"); n_cd += 1; }
            "slots" => {
                let s = slots_for(c[1].parse().unwrap(), c[2] == "1");
                let pair = |p: [u8; 2]| format!("{},{}", p[0], p[1]);
                let got = format!("{};{};{};{};{}", pair(s.x), pair(s.h), pair(s.m), pair(s.s), s.show.iter().map(|b| if *b { "1" } else { "0" }).collect::<String>());
                assert_eq!(got, c[3], "{at}"); n_cd += 1;
            }
            "units" => { assert_eq!(units_for(c[1].parse().unwrap(), c[2] == "1"), c[3], "{at}"); n_cd += 1; }
            "secondsleft" => { assert_eq!(seconds_left(f(c[1]), f(c[2])), c[3].parse::<u64>().unwrap(), "{at}"); n_cd += 1; }
            "ease" => { let got = ease_in_out_back(f(c[1]), f(c[2])); assert!((got - f(c[3])).abs() < 1e-12, "{at}: got {got}"); n_cd += 1; }
            "morph" => {
                let got = morph(digit(c[1].parse().unwrap()), digit(c[2].parse().unwrap()), f(c[3]), 15.0);
                let want: Vec<f64> = c[4].split(',').map(|x| x.parse().unwrap()).collect();
                assert_eq!(want.len(), 26, "{at}");
                for (i, (g, w)) in got.iter().zip(&want).enumerate() { assert!((g - w).abs() < 1e-6, "{at}: point {i}: got {g}, want {w}"); }
                n_cd += 1;
            }
            "sunpos" => {
                let (alt, az) = sun::position(f(c[3]), f(c[1]), f(c[2]));
                assert!((alt - f(c[4])).abs() < 0.05, "{at}: altitude {alt}");
                let want = f(c[5]); let d = ((az - want + 540.0).rem_euclid(360.0) - 180.0).abs();
                // near the poles the azimuth swings fast; compare it only where the sun is well clear of the zenith
                if f(c[1]).abs() < 60.0 && alt.abs() < 80.0 { assert!(d < 0.3, "{at}: azimuth {az} vs {want}"); }
                n_cd += 1;
            }
            "sunevents" => {
                let ev = sun::events(f(c[3]), f(c[1]), f(c[2]));
                for (name, got, want) in [("prevRise", ev.prev_rise, f(c[4])), ("prevSet", ev.prev_set, f(c[5])), ("nextRise", ev.next_rise, f(c[6])), ("nextSet", ev.next_set, f(c[7]))] {
                    if want.is_nan() { assert!(got.is_nan(), "{at}: {name} should be none, got {got}"); }
                    else { assert!(got.is_finite() && (got - want).abs() < 90_000.0, "{at}: {name} {got} vs {want} ({} s off)", (got - want) / 1000.0); }
                }
                n_cd += 1;
            }
            "countdown" => {
                // New York time, the page's countdown: the phase and the digits, with and without seconds
                let zone = wobbly_core::tz::Zone::load("America/New_York").expect("America/New_York zoneinfo");
                for (show_seconds, want) in [(true, c[4]), (false, c[5])] {
                    let cfg = wobbly_core::config::Config { clock_mode: "countdown".into(), timer_target: c[1].into(), hide_seconds: !show_seconds, twenty_four_hour: Some(true), ..Default::default() };
                    let now = f(c[2]);
                    let target = wobbly_core::clock::target_ms(&cfg, &zone).unwrap();
                    let phase = match wobbly_core::clock::phase_of(target, now, &zone) { wobbly_core::clock::Phase::Counting => "counting", wobbly_core::clock::Phase::Done => "done", wobbly_core::clock::Phase::Over => "over" };
                    assert_eq!(phase, c[3], "{at}: phase");
                    let got = wobbly_core::clock::display_text(&cfg, &zone, now);
                    if want == "time" { assert_eq!(got, wobbly_core::clock::time_text(&cfg, &zone, now), "{at}: after the day the clock shows the time"); } else { assert_eq!(got, want, "{at}"); }
                }
                n_cd += 1;
            }
            "thanksgiving" => { assert_eq!(wobbly_core::season::thanksgiving_day(c[1].parse().unwrap()), c[2].parse::<i64>().unwrap(), "{at}"); n_cd += 1; }
            "season" => { assert_eq!(wobbly_core::season::is_christmas_season(c[1].parse().unwrap(), c[2].parse().unwrap(), c[3].parse().unwrap()), c[4] == "1", "{at}"); n_cd += 1; }
            "tz" => {}                       // read by tests/tz.rs
            other => panic!("unknown vector kind {other} at {at}"),
        }
    }
    assert!(n_dim > 500 && n_cd > 100, "too few vectors read: {n_dim} brightness, {n_cd} countdown");
}

#[test]
fn text_and_limits() {
    assert_eq!(text_of(&groups_for(12 * 3600 + 5 * 60 + 30, true)), "12:05:30");
    assert_eq!(text_of(&groups_for(86400 * 100, false)), "100");
    for secs in [0u64, 59, 3600, 86400, 86400 * 100 + 7, 86400 * 999 + 86399] {
        let with: usize = groups_for(secs, true).iter().map(|g| g.len()).sum();
        let without: usize = groups_for(secs, false).iter().map(|g| g.len()).sum();
        assert!(with <= MAX_DIGITS_WITH_SECONDS && without <= MAX_DIGITS_WITHOUT_SECONDS, "{secs}: {with} / {without}");
    }
}

#[test]
fn brightness_basics() {
    assert!(!dimming_on(1.0, 1.0) && dimming_on(1.0, 0.25));
    assert_eq!(level(f64::NAN), 1.0);
    assert_eq!(level(0.01), 0.1);
}

#[test]
fn digit_table_is_the_web_pages() {
    // the first and last numbers of the first digit, as in js/config.js dd[0]
    let d0 = digit(0);
    assert_eq!((d0[0], d0[1], d0[24], d0[25]), (254.0, 47.0, 231.0, 75.0));
    assert_eq!(wobbly_core::digits::DIGIT_COUNT, 10);
}
